# Solution code
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        union(u, v)

    # Count component sizes
    size = {}
    for i in range(1, n + 1):
        root = find(i)
        size[root] = size.get(root, 0) + 1

    sizes = list(size.values())

    def generate_lucky_numbers(max_val):
        lucky = []
        q = ['4', '7']
        while q:
            curr = q.pop(0)
            val = int(curr)
            if val <= max_val + 10:
                lucky.append(val)
                if len(curr) < 7:
                    q.append(curr + '4')
                    q.append(curr + '7')
        return sorted(lucky)

    lucky_numbers = generate_lucky_numbers(max(sizes) * 5) if sizes else []

    if sizes:
        component_count = len(sizes)
        max_component_sum = sum(sizes)

        dp = [-1] * (max_component_sum + 1)
        dp[0] = 0

        for s in sizes:
            for j in range(max_component_sum, s - 1, -1):
                if dp[j - s] != -1:
                    new_val = dp[j - s] + 1
                    if new_val < dp[j] or dp[j] == -1:
                        dp[j] = new_val

        min_road = float('inf')
        for val in lucky_numbers:
            if val <= max_component_sum and dp[val] != -1:
                min_road = min(min_road, dp[val] - 1)

        if min_road == float('inf'):
            return "-1"
        return str(min_road) + "\n"
    else:
        # All islands are isolated, single nodes each
        # Check max lucky number <= n
        max_val = n
        lucky = []
        q = ['4', '7']
        while q:
            curr = q.pop(0)
            val = int(curr)
            if val <= max_val + 10:
                lucky.append(val)
                if len(curr) < 7:
                    q.append(curr + '4')
                    q.append(curr + '7')
        lucky = sorted(lucky)

        min_road = float('inf')
        for val in lucky:
            if val <= max_val:
                min_road = min(min_road, 1)  # Merge 2 components

        if min_road == float('inf'):
            return "-1"
        return str(min_road) + "\n"

