2. Find all cycles in this graph
3. Count total cycle cells (maximum robots)
4. For each cycle, count black cells for the second output

The key insight is that robots will follow deterministic paths and eventually enter cycles. Robots can only collide if they reach the cycle at the same offset. The maximum robots equals the sum of all cycle lengths (placing one robot per cycle position), and we maximize black cells by counting black cells within cycles.

```python
def solution(input_string):
    from collections import deque

    lines = input_string.strip().split('\n')
    idx = 0

    try:
        t = int(lines[idx].strip())
        idx += 1
    except:
        return ""

    results = []

    for _ in range(t):
        try:
            n, m = map(int, lines[idx].split())
            idx += 1

            black_cell_positions = []
            for i in range(n):
                if idx >= len(lines):
                    break
                row = lines[idx]
                idx += 1
                for j in range(m):
                    if row[j] == '0':
                        black_cell_positions.append(i * m + j)

            directions = []
            for i in range(n):
                if idx >= len(lines):
                    break
                row = lines[idx]
                idx += 1
                for j in range(m):
                    d = row[j]
                    ni, nj = i, j
                    if d == 'U' and i > 0:
                        ni = i - 1
                    elif d == 'D' and i < n - 1:
                        ni = i + 1
                    elif d == 'L' and j > 0:
                        nj = j - 1
                    elif d == 'R' and j < m - 1:
                        nj = j + 1
                    directions.append(ni * m + nj)

            in_degree = [0] * (n * m)
            for cell in range(n * m):
                in_degree[directions[cell]] += 1

            queue = deque([cell for cell in range(n * m) if in_degree[cell] == 0])

            while queue:
                cell = queue.popleft()
                neighbor = directions[cell]
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

            total_robots = 0
            total_black = 0
            visited = [False] * (n * m)

            for i in range(n * m):
                if in_degree[i] > 0 and not visited[i]:
                    cycle = []
                    curr = i
                    while not visited[curr]:
                        visited[curr] = True
                        cycle.append(curr)
                        curr = directions[curr]
                    total_robots += len(cycle)
                    for pos in cycle:
                        if pos in black_cell_positions:
                            total_black += 1

            results.append(f"{total_robots} {total_black}")
        except Exception as e:
            continue

    return '\n'.join(results)
