import math
import os

MOD = 1051131

def multiply(A, B, n):
    """Matrix multiplication mod MOD"""
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for k in range(n):
            if A[i][k] == 0:
                continue
            for j in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(A, t, n):
    """Matrix exponentiation mod MOD"""
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = [row[:] for row in A]
    while t > 0:
        if t % 2 == 1:
            result = multiply(result, base, n)
        base = multiply(base, base, n)
        t //= 2
    return result

def multiply_vec_mat(vec, T, n):
    """Vector-matrix multiplication mod MOD"""
    result = [0] * n
    for i in range(n):
        for j in range(n):
            result[i] = (result[i] + vec[j] * T[j][i]) % MOD
    return result

def generate_a(m, s, given_a):
    """Generate complete array a with 2^m elements"""
    a = given_a[:]
    for i in range(s, 2**m):
        vals = []
        for v in given_a:
            vals.append(v)
        a.append((101 * a[-1] + 10007) % MOD)
    return a

def solution(input_string):
    lines = input_string.strip().split('\n')
    parts = lines[0].split()
    m, t, s = int(parts[0]), int(parts[1]), int(parts[2])
    given_a = list(map(int, lines[1].split()))

    n = 2**m

    # Complete array a
    a = given_a[:]
    for i in range(s, n):
        a.append((101 * a[-1] + 10007) % MOD)

    # Transition matrix T[i][j] = 2^gcd(i+1, j+1)
    T = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            g = math.gcd(i + 1, j + 1)
            T[i][j] = pow(2, g)

    # Compute T^t
    T_t = mat_pow(T, t, n)

    # Final vector: x_init * T^t
    x_final = [0] * n
    for i in range(n):
        for j in range(n):
            x_final[i] = (x_final[i] + a[j] * T_t[j][i]) % MOD

    # XOR sum
    xor_sum = 0
    for val in x_final:
        xor_sum ^= val

    return f"{xor_sum}\n"

if __name__ == "__main__":
