1. A square is a solid frame (border) with linewidth 1
2. Must be at least 2×2
3. Can be axis-aligned OR rotated (sides parallel to diagonals)
4. Must not touch any foreign 1s (by side or corner)
5. Must contain at least one 1

Let me write a solution that handles both types of squares:

```python
# Your solution code
def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    t = int(lines[0])
    results = []

    for case_idx in range(t):
        pos = 1 + 2 * case_idx
        n, m = map(int, lines[pos].split())
        pos += 1

        matrix_data = lines[pos:pos + n]
        pos += n

        # Convert to set of positions with '1'
        ones = set()
        for r in range(n):
            for c in range(m):
                if matrix_data[r][c] == '1':
                    ones.add((r, c))

        count = 0

        # Check axis-aligned squares
        for r_start in range(n):
            for c_start in range(m):
                size = 2
                while r_start + size <= n and c_start + size <= m:
                    r_end = r_start + size - 1
                    c_end = c_start + size - 1

                    # Verify all 4 sides are all 1s
                    sides_ok = True
                    # Top row
                    for c in range(c_start, c_end + 1):
                        if (r_start, c) not in ones:
                            sides_ok = False
                            break
                    if not sides_ok:
                        break
                    # Bottom row
                    for c in range(c_start, c_end + 1):
                        if (r_end, c) not in ones:
                            sides_ok = False
                            break
                    if not sides_ok:
                        break
                    # Left column
                    for r in range(r_start, r_end + 1):
                        if (r, c_start) not in ones:
                            sides_ok = False
                            break
                    if not sides_ok:
                        break
                    # Right column
                    for r in range(r_start, r_end + 1):
                        if (r, c_end) not in ones:
                            sides_ok = False
                            break
                    if not sides_ok:
                        break

                    side_cells = set()
                    for c in range(c_start, c_end + 1):
                        side_cells.add((r_start, c))
                        side_cells.add((r_end, c))
                    for r in range(r_start + 1, r_end):
                        side_cells.add((r, c_start))
                        side_cells.add((r, c_end))

                    # Check no foreign 1s touch the square
                    valid = True
                    for r in range(r_start, r_end + 1):
                        for c in range(c_start, c_end + 1):
                            if (r, c) in ones:
                                for dr in [-1, 0, 1]:
                                    for dc in [-1, 0, 1]:
                                        if dr == 0 and dc == 0:
                                            continue
                                        nr, nc = r + dr, c + dc
                                        if 0 <= nr < n and 0 <= nc < m:
                                            if (nr, nc) in ones and (nr, nc) not in side_cells:
                                                valid = False
                                                break
                                    if not valid:
                                        break
                                if not valid:
                                    break
                        if not valid:
                            break

                    if valid:
                        count += 1
                    else:
                        break
                size += 1

        # Check diagonal squares (diamonds aligned with grid diagonals)
        for r in range(n):
            for c in range(m):
                k = 1
                while r + k < n and c + k < m and r - k >= 0 and c - k >= 0:
                    # Four corners of diamond at half-width k
                    top = (r - k, c)
                    bottom = (r + k, c)
                    left = (r, c - k)
                    right = (r, c + k)

                    if top in ones and bottom in ones and left in ones and right in ones:
                        # Diamond is valid if k > 0
                        if k == 0:
                            k += 1
                            continue

                        # Build set of all diamond border cells
                        diamond_border = set()
                        # Corners and their 8 neighbors (the border)
                        for corner in [top, bottom, left, right]:
                            for dr in [-1, 0, 1]:
                                for dc in [-1, 0, 1]:
                                    nr, nc = corner[0] + dr, corner[1] + dc
                                    diamond_border.add((nr, nc))

                        # Check all border cells have 1
                        border_ok = True
                        for cell in diamond_border:
                            if cell not in ones:
                                border_ok = False
                                break
                        if not border_ok:
                            k += 1
                            continue

                        # Check no foreign 1s touch border
                        valid = True
                        for cell in diamond_border:
                            cr, cc = cell
                            for dr in [-1, 0, 1]:
                                for dc in [-1, 0, 1]:
                                    if dr == 0 and dc == 0:
                                        continue
                                    nr, nc = cr + dr, cc + dc
                                    if 0 <= nr < n and 0 <= nc < m:
                                        if (nr, nc) in ones and (nr, nc) not in diamond_border:
                                            valid = False
                                            break
                                if not valid:
                                    break
                            if not valid:
                                break

                        if valid:
                            count += 1

                        k += 1
                    else:
                        k += 1

        results.append(str(count))

    return '\n'.join(results)
