def solution(input_str):
    """
    Problem: Given a tree where vertices have ice cream types,
    build graph G where edge exists between types if they coexist.
    Find chromatic number of G and proper coloring.

    Key insight: At each vertex, all its ice cream types form a clique in G.
    The chromatic number equals max number of types at any vertex.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    vertex_ice_creams = []
    for line in lines[1:n+1]:
        parts = line.split()
        si = int(parts[0])
        types = list(map(int, parts[1:si+1]))
        vertex_ice_creams.append(types)

    if m == 0:
        return "0\n"

    # Maximum ice cream types at any vertex = chromatic number
    max_deg = max(len(types) for types in vertex_ice_creams) if vertex_ice_creams else 1

    # For each ice cream type, which vertices contain it
    type_to_vertices = collections.defaultdict(list)
    for vertex, types in enumerate(vertex_ice_creams):
        for t in types:
            type_to_vertices[t].append(vertex)

    # Color assignment using greedy approach
    # Process vertices sorted by number of types (largest first)
    sorted_vertices = sorted(range(n), key=lambda v: len(vertex_ice_creams[v]), reverse=True)

    result_ice_creams = [0] * (m + 1)
    color_at_vertex = [set() for _ in range(n + 1)]

    for vertex in sorted_vertices:
        types = vertex_ice_creams[vertex]
        for t in types:
            # Find smallest color not used at this vertex
            used = color_at_vertex[vertex]
            color = 1
            while color in used:
                color += 1
            result_ice_creams[t] = color
            used.add(color)

    # Build output with trailing space as expected
    colors = [str(result_ice_creams[i]) for i in range(1, m + 1)]
    return f"{max_deg}\n" + " ".join(colors) + " \n"

