def solution(input_text: str) -> str:
    lines = input_text.strip().split('\n')
    n, m = map(int, lines[0].split())

    roads = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        roads.append((a, b))

    def cross(e1, e2):
        a, b = sorted(e1)
        c, d = sorted(e2)
        if a == c or a == d or b == c or b == d:
            return False
        def between(x, l, r):
            return not (l < r <= x or x < l or (x <= l or x >= r))
        return (between(c, a, b)) != (between(d, a, b))

    graph = [[] for _ in range(2 * m)]
    for i in range(m):
        for j in range(i + 1, m):
            if cross(roads[i], roads[j]):
                graph[2 * i].append(2 * j + 1)
                graph[2 * i + 1].append(2 * j)
                graph[2 * j].append(2 * i + 1)
                graph[2 * j + 1].append(2 * i)

    visited, order = [False] * (2 * m), []
    def dfs1(u):
        if visited[u]: return
        visited[u] = True
        for v in graph[u]: dfs1(v)
        order.append(u)
    for i in range(2 * m):
        if not visited[i]: dfs1(i)

    rev = [[] for _ in range(2 * m)]
    for u in range(2 * m):
        for v in graph[u]:
            rev[v].append(u)

    comp = [-1] * (2 * m)
    def dfs2(u, c):
        stack = [u]
        comp[u] = c
        while stack:
            v = stack.pop()
            for w in rev[v]:
                if comp[w] == -1:
                    comp[w] = c
                    stack.append(w)
    cnt = 0
    for i in range(2 * m - 1, -1, -1):
        if comp[i] == -1: dfs2(i, cnt); cnt += 1

    for i in range(m):
        if comp[2 * i] == comp[2 * i + 1]:
            return "Impossible\n"
    return "".join(["i" if comp[2 * i] < comp[2 * i + 1] else "o" for i in range(m)]) + "\n"
