def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Map value to index for quick lookup
    val_to_idx = {val: i for i, val in enumerate(p)}

    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x != root_y:
            parent[root_x] = root_y

    # Union elements that must be in the same set
    for i in range(n):
        val = p[i]
        if (a - val) in val_to_idx:
            union(i, val_to_idx[a - val])
        if (b - val) in val_to_idx:
            union(i, val_to_idx[b - val])

    # Group by component
    comp_elements = {}
    for i in range(n):
        root = find(i)
        if root not in comp_elements:
            comp_elements[root] = []
        comp_elements[root].append(i)

    result = [0] * n
    possible = True

    for root, indices in comp_elements.items():
        # Check if can be in A
        can_a = all((a - p[i]) in val_to_idx for i in indices)

        if can_a:
            for i in indices:
                result[i] = 0
        else:
            # Check if can be in B
            can_b = all((b - p[i]) in val_to_idx for i in indices)

            if can_b:
                for i in indices:
                    result[i] = 1
            else:
                # Impossible
                possible = False
                break

    if possible:
        return f"YES\n{' '.join(map(str, result))} "
    else:
        return "NO\n"
