    if num_sets > 0 and b > min_b + 25 * (num_sets - 1) + 23 * awins:
        return False

    return True

def greedy_construct(a, b, awins, bwins):
    sets = []
    remaining_a, remaining_b = a, b

    # Allocate to winning sets first
    for _ in range(awins):
        if remaining_a >= 25 and remaining_b <= 23:
            sets.append((25, min(remaining_b, 23)))
            remaining_a -= 25
        elif remaining_b >= 25 and remaining_a <= 23:
            sets.append((min(remaining_a, 23), 25))
            remaining_b -= 25
        elif remaining_a >= 25:
            sets.append((25, 0))
            remaining_a -= 25
        elif remaining_b >= 25:
            sets.append((0, 25))
            remaining_b -= 25

    return sets
